/**
 * calibration/bug-corpus.ts — the filler corpus of the Phase B bug trials (P6;
 * design/specs/local-calibration-design.md section 4.3, F5). GENERATED, pinned:
 * nine real source files of this repository (MIT), copied verbatim from the frozen
 * benchmark snapshots in scripts/llm-ext/benchmark-fixtures/ (scan-folder/src at
 * commit 8f5547d, and code-task/). Embedded here because the plugin ships only
 * dist/, and calibration runs on the user's machine.
 *
 * Checked once for real bugs by a model (2026-10-29, llm-ext llm ask, free
 * profile, glm-5.3-flash, one file per request): it flagged cluster/jsonl.ts
 * (appendJsonlSync writes through an asynchronous stream), so that file is
 * excluded (spec 4.3: flagged files are excluded). The other nine: no real bugs.
 *
 * BUG_CORPUS_SHA256 pins the content (a unit test recomputes it): a change to
 * any file is a fixture change and must bump FIXTURE_VERSION (record.ts).
 */

export const BUG_CORPUS_SHA256 = "4fb50e3b5ee95892bf746c0497143aea214d57847dc5aaa5344c2389d0ad4af4";

export const BUG_CORPUS: ReadonlyArray<{ path: string; text: string }> = [
  { path: "src/project-root.ts", text: "/**\n * Resolve the user's MAIN project directory that report writes anchor on, so\n * reports ALWAYS land under `<main-project-dir>/reports/<component>/` — never in\n * a subfolder, a worktree, an enclosing repo, or the plugin install cache.\n *\n * SINGLE SOURCE OF TRUTH — every report-path resolver in the server routes here.\n *\n * The main project dir is `$CLAUDE_PROJECT_DIR` (the directory Claude Code is\n * operating in). It does NOT necessarily coincide with a git folder, so we must\n * NOT use git to find the root:\n *   - linked worktrees: the git main-worktree ≠ the dir the agent works in;\n *   - a monorepo whose subfolders each have their OWN git while the root has\n *     none: `git` from anywhere resolves to a subfolder repo, never the root;\n *   - a git-less project root.\n * In every one of those cases `git worktree list` (or any git-root climb) picks\n * the WRONG directory and scatters reports outside the project. So this resolver\n * deliberately uses NO git at all.\n *\n * Resolution order (highest precedence first):\n *   1. `override` — an explicit caller-supplied root (e.g. an `output_dir` /\n *      `mainRoot` the caller already resolved). Honored verbatim.\n *   2. `$CLAUDE_PROJECT_DIR` when it exists on disk — the main project dir Claude\n *      Code sets in the MCP-stdio env. Used VERBATIM.\n *   3. `process.cwd()` — last resort for a direct CLI run with no\n *      CLAUDE_PROJECT_DIR (the user's shell cwd is their project). NEVER git.\n *\n * A per-call explicit `output_dir` still overrides everything upstream of this.\n */\n\nimport { existsSync } from \"node:fs\";\n\nexport function resolveProjectMainRoot(override?: string): string {\n  if (override && override.length > 0) return override;\n\n  const projDir = process.env.CLAUDE_PROJECT_DIR;\n  if (projDir && projDir.length > 0 && existsSync(projDir)) return projDir;\n\n  return process.cwd();\n}\n" },
  { path: "src/doc-inventory.ts", text: "// ── Doc-inventory extraction (A5, TRDD-828238b5) ───────────────────────\n//\n// Single source of truth for the COUNTS and NAME LISTS that the docs restate\n// by hand (and that drifted on every tool addition during the deep audit).\n// These pure functions parse the authoritative declarations straight from the\n// source tree so the doc-consistency test (doc-consistency.test.ts) can assert\n// the README/rule docs match the code. No server import (index.ts runs main()\n// on import) — everything is read as text + regex.\n\nimport { readFileSync, readdirSync } from \"node:fs\";\nimport { join, dirname } from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\n\n/** Repo root = two levels up from this module (mcp-server/src → repo root). */\nexport function repoRoot(): string {\n  return join(dirname(fileURLToPath(import.meta.url)), \"..\", \"..\");\n}\n\n/**\n * Core/utility MCP tool names — declared inline in buildTools()'s `allTools`\n * array (extracted to tools/definitions.ts in B1 Phase 4, TRDD-63314265),\n * each as a 6-space-indented `name: \"x\",`. The 6-space anchor excludes the\n * 2-space-indented JSON-schema `name:` fields elsewhere in the file.\n */\nexport function readCoreToolNames(root: string = repoRoot()): string[] {\n  const src = readFileSync(\n    join(root, \"mcp-server\", \"src\", \"tools\", \"definitions.ts\"),\n    \"utf-8\",\n  );\n  return matchAll(src, /^ {6}name: \"([a-z0-9_]+)\",$/gm);\n}\n\n/**\n * Mass-scout + model-qualification MCP tool names — declared in MASS_SCOUT_TOOLS\n * in mass_scouting/mcp-tools.ts, each as a 4-space-indented `name: \"x\",`.\n */\nexport function readMassScoutToolNames(root: string = repoRoot()): string[] {\n  const src = readFileSync(\n    join(root, \"mcp-server\", \"src\", \"mass_scouting\", \"mcp-tools.ts\"),\n    \"utf-8\",\n  );\n  return matchAll(src, /^ {4}name: \"([a-z0-9_]+)\",$/gm);\n}\n\n/** Every MCP tool the server exposes (core + mass-scout/model-qual). */\nexport function readAllToolNames(root: string = repoRoot()): string[] {\n  return [...readCoreToolNames(root), ...readMassScoutToolNames(root)];\n}\n\n/** API-preset keys — declared in API_PRESETS in config.ts. */\nexport function readApiPresetNames(root: string = repoRoot()): string[] {\n  const src = readFileSync(join(root, \"mcp-server\", \"src\", \"config.ts\"), \"utf-8\");\n  const start = src.indexOf(\"export const API_PRESETS\");\n  if (start === -1) throw new Error(\"API_PRESETS not found in config.ts\");\n  // Keys are 2-space-indented quoted strings until the next top-level `};`.\n  const end = src.indexOf(\"\\n};\", start);\n  const block = src.slice(start, end === -1 ? undefined : end);\n  return matchAll(block, /^ {2}\"([a-z0-9-]+)\": \\{$/gm);\n}\n\n/** Slash-command names — the frontmatter `name:` of each commands/*.md. */\nexport function readCommandNames(root: string = repoRoot()): string[] {\n  const dir = join(root, \"commands\");\n  const names: string[] = [];\n  for (const f of readdirSync(dir)) {\n    if (!f.endsWith(\".md\")) continue;\n    const src = readFileSync(join(dir, f), \"utf-8\");\n    const fm = frontmatter(src);\n    const m = fm.match(/^name:\\s*(\\S+)\\s*$/m);\n    if (!m) throw new Error(`commands/${f} has no frontmatter name:`);\n    names.push(m[1]!);\n  }\n  return names.sort();\n}\n\n/** Agent names — one agents/*.md per agent. */\nexport function readAgentNames(root: string = repoRoot()): string[] {\n  const dir = join(root, \"agents\");\n  return readdirSync(dir)\n    .filter((f) => f.endsWith(\".md\"))\n    .map((f) => f.replace(/\\.md$/, \"\"))\n    .sort();\n}\n\n// ── helpers ────────────────────────────────────────────────────────────\n\nfunction matchAll(text: string, re: RegExp): string[] {\n  const out: string[] = [];\n  for (const m of text.matchAll(re)) out.push(m[1]!);\n  return out;\n}\n\n/** Return the YAML frontmatter block (between the first two `---` lines), or \"\". */\nfunction frontmatter(src: string): string {\n  if (!src.startsWith(\"---\")) return \"\";\n  const end = src.indexOf(\"\\n---\", 3);\n  return end === -1 ? \"\" : src.slice(3, end);\n}\n" },
  { path: "src/cluster/unionfind.ts", text: "// Union-find with path compression + union by rank, keyed by arbitrary\n// string ids. Used by phase1_batch.ts and phase2_verify.ts to merge\n// clusters as the LLM groups items together.\n//\n// In-memory only — checkpoint.ts mirrors the (item_id → parent_id) edges\n// to SQLite so resume can rehydrate the structure. The transitive-closure\n// merge logic from §7 / Q12 lives in phase2_verify.ts; this module only\n// provides the data structure.\n\nexport class UnionFind {\n  private parent = new Map<string, string>();\n  private rank = new Map<string, number>();\n  private sizes = new Map<string, number>();\n\n  /**\n   * Add an item if it does not already exist. New items start as\n   * their own cluster (singleton).\n   */\n  add(id: string): void {\n    if (this.parent.has(id)) return;\n    this.parent.set(id, id);\n    this.rank.set(id, 0);\n    this.sizes.set(id, 1);\n  }\n\n  has(id: string): boolean {\n    return this.parent.has(id);\n  }\n\n  /**\n   * Find the root of `id` with path compression. Throws if the id is\n   * not in the structure — callers should always `add()` first.\n   */\n  find(id: string): string {\n    const p = this.parent.get(id);\n    if (p === undefined) throw new Error(`UnionFind.find: unknown id '${id}'`);\n    if (p === id) return id;\n    const root = this.find(p);\n    this.parent.set(id, root);\n    return root;\n  }\n\n  /**\n   * Union two items. Returns the root of the merged set, or null if\n   * the two were already in the same set.\n   */\n  union(a: string, b: string): string | null {\n    const ra = this.find(a);\n    const rb = this.find(b);\n    if (ra === rb) return null;\n    const ranka = this.rank.get(ra) ?? 0;\n    const rankb = this.rank.get(rb) ?? 0;\n    const sizea = this.sizes.get(ra) ?? 1;\n    const sizeb = this.sizes.get(rb) ?? 1;\n    let newRoot: string;\n    let absorbed: string;\n    if (ranka < rankb) {\n      this.parent.set(ra, rb);\n      newRoot = rb;\n      absorbed = ra;\n    } else if (ranka > rankb) {\n      this.parent.set(rb, ra);\n      newRoot = ra;\n      absorbed = rb;\n    } else {\n      this.parent.set(rb, ra);\n      this.rank.set(ra, ranka + 1);\n      newRoot = ra;\n      absorbed = rb;\n    }\n    this.sizes.set(newRoot, sizea + sizeb);\n    this.sizes.delete(absorbed);\n    return newRoot;\n  }\n\n  /**\n   * Size of the cluster containing `id`. Throws on unknown id.\n   */\n  sizeOf(id: string): number {\n    const root = this.find(id);\n    return this.sizes.get(root) ?? 1;\n  }\n\n  /**\n   * Number of distinct clusters currently in the structure.\n   */\n  numClusters(): number {\n    return this.sizes.size;\n  }\n\n  /**\n   * Materialise the current partition as Map<root, item[]>. Linear pass\n   * — call infrequently (typically only at emit time in phase4).\n   */\n  partition(): Map<string, string[]> {\n    const out = new Map<string, string[]>();\n    for (const id of this.parent.keys()) {\n      const root = this.find(id);\n      let arr = out.get(root);\n      if (!arr) {\n        arr = [];\n        out.set(root, arr);\n      }\n      arr.push(id);\n    }\n    return out;\n  }\n\n  /**\n   * Snapshot the (item → parent) edges. Used by checkpoint.ts to mirror\n   * the structure to SQLite. Note: this is the LAZY edges (compressed\n   * during find()), not the original union order — that's fine because\n   * the partition is what matters.\n   */\n  edges(): Array<[string, string]> {\n    return Array.from(this.parent.entries());\n  }\n\n  /**\n   * Rehydrate from a previous `edges()` snapshot (from checkpoint).\n   * Items not already present are added; `find()` on any reconstructed\n   * id will compress the path on demand.\n   */\n  static fromEdges(edges: Iterable<[string, string]>): UnionFind {\n    const uf = new UnionFind();\n    // First pass: add every id as a singleton.\n    for (const [a, b] of edges) {\n      uf.add(a);\n      uf.add(b);\n    }\n    // Second pass: install parent pointers without rank/size mutation.\n    // We then walk find() on every node to recompute sizes from scratch.\n    for (const [a, b] of edges) {\n      uf.parent.set(a, b);\n    }\n    // Recompute sizes by counting cluster membership from current parent map.\n    const counts = new Map<string, number>();\n    for (const id of uf.parent.keys()) {\n      const root = uf.find(id);\n      counts.set(root, (counts.get(root) ?? 0) + 1);\n    }\n    uf.sizes = counts;\n    // Rank is approximate after rehydrate — we leave existing ranks as 0\n    // which biases future unions slightly toward depth balance, but\n    // correctness is preserved.\n    return uf;\n  }\n}\n" },
  { path: "src/rule-install.ts", text: "/**\n * Install (or update) the plugin's \"how to use me\" rule into the Claude rules\n * dir (`~/.claude/rules/use-llm-externalizer.md`).\n *\n * WHY THE MCP SERVER DOES THIS: Claude Code's file-write hooks gate the main\n * agent's Write/Edit/Bash tools and can forbid writing outside the project\n * folder. The MCP server, however, runs as a SUBPROCESS whose own filesystem\n * writes are not gated by those hooks — so it can place the rule in the user's\n * global config where the agent cannot. The rule then loads in every future\n * session so any agent knows how to drive this plugin.\n *\n * Safety contract:\n *   - BEST-EFFORT: never throws into the caller; the server must boot even if\n *     this fails (returns a status object instead).\n *   - CONTENT-GATED: writes only when the destination is absent or differs, so\n *     repeated server starts cause zero churn after the first sync.\n *   - ATOMIC: tmp-file + rename, so a crash mid-write never leaves a partial.\n *   - GUARDED: refuses to write anywhere except under $HOME, an explicit\n *     $CLAUDE_CONFIG_DIR, or the OS temp dir (os.tmpdir(), the test sandbox) —\n *     never an arbitrary path.\n *   - OPT-OUT: set LLM_EXT_INSTALL_RULE=0 (or \"false\") to disable entirely.\n */\n\nimport {\n  existsSync,\n  mkdirSync,\n  readFileSync,\n  writeFileSync,\n  renameSync,\n  realpathSync,\n  unlinkSync,\n} from \"node:fs\";\nimport { randomBytes } from \"node:crypto\";\nimport { homedir, tmpdir } from \"node:os\";\nimport { dirname, join, resolve, sep } from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\n\nexport const RULE_FILENAME = \"use-llm-externalizer.md\";\n\n/**\n * Resolve the bundled rule shipped with the plugin. Prefers $CLAUDE_PLUGIN_ROOT\n * (set when running as an installed plugin); falls back to a path relative to\n * this module (works both bundled in dist/ and unbundled in src/). Returns null\n * when no candidate exists on disk.\n */\nexport function resolveBundledRulePath(): string | null {\n  const candidates: string[] = [];\n  const pluginRoot = process.env.CLAUDE_PLUGIN_ROOT;\n  if (pluginRoot && pluginRoot.length > 0) {\n    candidates.push(join(resolve(pluginRoot), \"rules\", RULE_FILENAME));\n  }\n  try {\n    // dist/index.js → <plugin>/mcp-server/dist; src/rule-install.ts →\n    // <plugin>/mcp-server/src. Either way, ../../rules is <plugin>/rules.\n    const here = dirname(fileURLToPath(import.meta.url));\n    candidates.push(resolve(here, \"..\", \"..\", \"rules\", RULE_FILENAME));\n  } catch {\n    /* import.meta.url unavailable (non-ESM context) — rely on the env var. */\n  }\n  for (const c of candidates) {\n    if (existsSync(c)) return c;\n  }\n  return null;\n}\n\n/** Resolve the Claude rules directory (`$CLAUDE_CONFIG_DIR/rules` or `~/.claude/rules`). */\nexport function resolveClaudeRulesDir(): string {\n  const cfg = process.env.CLAUDE_CONFIG_DIR;\n  const base = cfg && cfg.length > 0 ? resolve(cfg) : join(homedir(), \".claude\");\n  return join(base, \"rules\");\n}\n\nexport interface RuleInstallResult {\n  status: \"installed\" | \"updated\" | \"unchanged\" | \"skipped\" | \"error\";\n  dest: string;\n  detail?: string;\n}\n\n/** Canonicalise a path's deepest-existing prefix so symlinks can't smuggle a\n *  write outside the allowed roots. */\nfunction canonical(p: string): string {\n  try {\n    return realpathSync(p);\n  } catch {\n    const parent = dirname(p);\n    if (parent === p) return p;\n    return join(canonical(parent), p.slice(parent.length + (parent.endsWith(sep) ? 0 : 1)));\n  }\n}\n\n/** True iff `dir` sits under one of the allowed write roots (home / explicit\n *  CLAUDE_CONFIG_DIR / os.tmpdir()). Compared on canonical paths. */\nfunction underAllowedRoot(dir: string): boolean {\n  const d = canonical(dir);\n  const roots: string[] = [];\n  try {\n    roots.push(realpathSync(homedir()));\n  } catch {\n    roots.push(homedir());\n  }\n  if (process.env.CLAUDE_CONFIG_DIR && process.env.CLAUDE_CONFIG_DIR.length > 0) {\n    roots.push(canonical(resolve(process.env.CLAUDE_CONFIG_DIR)));\n  }\n  // os.tmpdir() instead of a literal \"/tmp\" so the test-sandbox root resolves\n  // correctly on every platform (e.g. Windows %TEMP%, where \"/tmp\" doesn't exist).\n  const tmp = tmpdir();\n  try {\n    roots.push(realpathSync(tmp));\n  } catch {\n    roots.push(tmp);\n  }\n  return roots.some((r) => d === r || d.startsWith(r + sep));\n}\n\n/**\n * Install/update the usage rule. See the file header for the full safety\n * contract. Tests inject `sourcePath` + `rulesDir` to stay offline and sandboxed.\n */\nexport function installUsageRule(\n  opts: { sourcePath?: string; rulesDir?: string } = {},\n): RuleInstallResult {\n  const optOut = process.env.LLM_EXT_INSTALL_RULE;\n  if (optOut === \"0\" || optOut === \"false\") {\n    return { status: \"skipped\", dest: \"\", detail: \"disabled via LLM_EXT_INSTALL_RULE\" };\n  }\n\n  const source = opts.sourcePath ?? resolveBundledRulePath();\n  if (!source || !existsSync(source)) {\n    return { status: \"error\", dest: \"\", detail: \"bundled rule source not found\" };\n  }\n\n  const rulesDir = opts.rulesDir ?? resolveClaudeRulesDir();\n  const dest = join(rulesDir, RULE_FILENAME);\n  if (!underAllowedRoot(rulesDir)) {\n    return {\n      status: \"error\",\n      dest,\n      detail: `refusing to write outside home / CLAUDE_CONFIG_DIR / tmp: ${rulesDir}`,\n    };\n  }\n\n  let desired: string;\n  try {\n    desired = readFileSync(source, \"utf-8\");\n  } catch (e) {\n    return { status: \"error\", dest, detail: `cannot read source: ${(e as Error).message}` };\n  }\n\n  const existed = existsSync(dest);\n  if (existed) {\n    try {\n      if (readFileSync(dest, \"utf-8\") === desired) return { status: \"unchanged\", dest };\n    } catch {\n      /* unreadable destination — fall through and overwrite it. */\n    }\n  }\n\n  // Random suffix on top of the pid so concurrent installUsageRule() calls in the\n  // SAME process never collide on the tmp name (pid alone is identical for both).\n  const tmp = dest + \".tmp.\" + process.pid + \".\" + randomBytes(4).toString(\"hex\");\n  try {\n    mkdirSync(rulesDir, { recursive: true });\n    writeFileSync(tmp, desired, \"utf-8\");\n    renameSync(tmp, dest);\n  } catch (e) {\n    // Best-effort cleanup so a failed rename never leaves an orphan .tmp file.\n    try {\n      unlinkSync(tmp);\n    } catch {\n      /* tmp may not exist (write itself failed) — nothing to clean up. */\n    }\n    return { status: \"error\", dest, detail: `write failed: ${(e as Error).message}` };\n  }\n  return { status: existed ? \"updated\" : \"installed\", dest };\n}\n" },
  { path: "src/cluster/embeddings.ts", text: "// Embeddings wrapper for cluster_synonyms (TRDD-220ea89f §4 + §6).\n// Two paths: load a precomputed float32 memmap (with sibling\n// .meta.json), or spawn compute_embeddings.py via `uv run` to compute\n// fresh embeddings from the input items. Both return a flat Float32Array\n// plus the dimension and the model id used.\n//\n// The memmap format is deliberately plain — `bytes_per_row = dim × 4`,\n// N rows packed row-major — so it can be produced by any tool (not just\n// our sidecar) as long as the sibling .meta.json matches.\n\nimport { spawnSync } from \"node:child_process\";\nimport {\n  existsSync,\n  mkdirSync,\n  readFileSync,\n  writeFileSync,\n  statSync,\n} from \"node:fs\";\nimport { dirname, join } from \"node:path\";\nimport type { ClusterInputItem } from \"./types.js\";\n\nexport interface EmbeddingsBundle {\n  /** Flat row-major float32 buffer of length N × dim. */\n  embeddings: Float32Array;\n  dim: number;\n  model: string;\n  /** \"loaded\" = read from existing .f32 file, \"computed\" = produced by\n   *  the Python sidecar during this call. */\n  source: \"loaded\" | \"computed\";\n  /** Path to the on-disk memmap file (callers may keep or delete it). */\n  path: string;\n}\n\nexport interface EmbeddingsMeta {\n  shape: [number, number];\n  dtype: string;\n  model: string;\n}\n\nconst F32_BYTES = 4;\n\n/** Read + validate the sibling .meta.json that every produced memmap has. */\nexport function readEmbeddingsMeta(path: string): EmbeddingsMeta {\n  const metaPath = path + \".meta.json\";\n  if (!existsSync(metaPath)) {\n    throw new Error(`embeddings meta sidecar missing: ${metaPath}`);\n  }\n  const raw = readFileSync(metaPath, \"utf-8\");\n  let meta: unknown;\n  try {\n    meta = JSON.parse(raw);\n  } catch (err) {\n    throw new Error(`embeddings meta is not valid JSON (${metaPath}): ${(err as Error).message}`, { cause: err });\n  }\n  if (\n    typeof meta !== \"object\" ||\n    meta === null ||\n    !Array.isArray((meta as EmbeddingsMeta).shape) ||\n    (meta as EmbeddingsMeta).shape.length !== 2 ||\n    typeof (meta as EmbeddingsMeta).shape[0] !== \"number\" ||\n    typeof (meta as EmbeddingsMeta).shape[1] !== \"number\"\n  ) {\n    throw new Error(`embeddings meta missing valid shape [N,D]: ${metaPath}`);\n  }\n  if (typeof (meta as EmbeddingsMeta).dtype !== \"string\") {\n    throw new Error(`embeddings meta missing dtype: ${metaPath}`);\n  }\n  if (typeof (meta as EmbeddingsMeta).model !== \"string\") {\n    throw new Error(`embeddings meta missing model: ${metaPath}`);\n  }\n  return meta as EmbeddingsMeta;\n}\n\n/** Read a float32 memmap. Validates byte-count against the meta's shape;\n *  throws on any size mismatch (T5 — embeddings dimension mismatch). */\nexport function loadEmbeddings(path: string, expectedN?: number): EmbeddingsBundle {\n  if (!existsSync(path)) throw new Error(`embeddings file missing: ${path}`);\n  const meta = readEmbeddingsMeta(path);\n  const [n, dim] = meta.shape;\n  if (meta.dtype !== \"float32\") {\n    throw new Error(`embeddings dtype must be float32 (got ${meta.dtype} in ${path}.meta.json)`);\n  }\n  if (n <= 0 || dim <= 0) {\n    throw new Error(`embeddings shape must be positive ([${n}, ${dim}])`);\n  }\n  if (expectedN !== undefined && n !== expectedN) {\n    throw new Error(`embeddings N mismatch: meta says ${n}, caller expected ${expectedN}`);\n  }\n  const expectedBytes = n * dim * F32_BYTES;\n  const stat = statSync(path);\n  if (stat.size !== expectedBytes) {\n    throw new Error(\n      `embeddings file size mismatch: ${path} is ${stat.size} bytes, ` +\n        `expected ${expectedBytes} = N(${n}) × D(${dim}) × ${F32_BYTES}`,\n    );\n  }\n  const buf = readFileSync(path);\n  // Use a fresh ArrayBuffer slice to guarantee 4-byte alignment for the typed array.\n  const ab = buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength);\n  const embeddings = new Float32Array(ab);\n  return { embeddings, dim, model: meta.model, source: \"loaded\", path };\n}\n\nexport interface ComputeEmbeddingsOpts {\n  /** Where the .f32 + .meta.json should land. Must be a writable directory. */\n  outDir: string;\n  /** Model id passed through to the sidecar. */\n  model: string;\n  /** Absolute path to compute_embeddings.py. */\n  scriptPath: string;\n  /** Optional override for the python launcher (default: \"uv\"). */\n  pythonRunner?: string;\n  /** Optional sentence cleaner — applied before writing the temp file. */\n  sentenceClean?: (s: string) => string;\n}\n\n/** Spawn the Python sidecar via `uv run` and load the resulting memmap.\n *  Throws on any non-zero exit, missing OK line, or post-load validation\n *  failure. */\nexport function computeEmbeddings(\n  items: ClusterInputItem[],\n  opts: ComputeEmbeddingsOpts,\n): EmbeddingsBundle {\n  if (items.length === 0) throw new Error(\"computeEmbeddings: empty items\");\n  if (!existsSync(opts.scriptPath)) {\n    throw new Error(`compute_embeddings.py not found: ${opts.scriptPath}`);\n  }\n  mkdirSync(opts.outDir, { recursive: true });\n  const inputPath = join(opts.outDir, \"_embedding_sentences.txt\");\n  const outputPath = join(opts.outDir, \"embeddings.f32\");\n  const clean = opts.sentenceClean ?? defaultSentenceClean;\n  writeFileSync(\n    inputPath,\n    items.map((it) => clean(it.sentence)).join(\"\\n\") + \"\\n\",\n    { encoding: \"utf-8\" },\n  );\n  const runner = opts.pythonRunner ?? \"uv\";\n  const argv = [\"run\", opts.scriptPath, \"--input\", inputPath, \"--output\", outputPath, \"--model\", opts.model];\n  const result = spawnSync(runner, argv, {\n    encoding: \"utf-8\",\n    stdio: [\"ignore\", \"pipe\", \"pipe\"],\n  });\n  if (result.error) {\n    throw new Error(`failed to spawn ${runner}: ${result.error.message}`);\n  }\n  if (result.status !== 0) {\n    throw new Error(\n      `compute_embeddings.py exited with status ${result.status}\\n` +\n        `stderr:\\n${result.stderr ?? \"\"}`,\n    );\n  }\n  // Expect a final line \"OK <n> <dim> <output_path>\"\n  const lines = (result.stdout ?? \"\").split(/\\r?\\n/).filter((l) => l.length > 0);\n  const okLine = lines[lines.length - 1] ?? \"\";\n  if (!okLine.startsWith(\"OK \")) {\n    throw new Error(\n      `compute_embeddings.py: missing OK line. Last stdout: ${JSON.stringify(okLine)}`,\n    );\n  }\n  const bundle = loadEmbeddings(outputPath, items.length);\n  return { ...bundle, source: \"computed\" };\n}\n\nfunction defaultSentenceClean(s: string): string {\n  return s.replace(/\\r?\\n/g, \" \").replace(/\\s+/g, \" \").trim();\n}\n\n/** Round-trip a synthetic embeddings bundle to disk (for tests + for\n *  letting callers persist a freshly-loaded set without re-computing). */\nexport function writeEmbeddingsToDisk(\n  embeddings: Float32Array,\n  dim: number,\n  model: string,\n  outPath: string,\n): void {\n  const n = embeddings.length / dim;\n  if (!Number.isInteger(n) || n <= 0) {\n    throw new Error(`writeEmbeddingsToDisk: bad shape (length=${embeddings.length}, dim=${dim})`);\n  }\n  mkdirSync(dirname(outPath), { recursive: true });\n  const buf = Buffer.from(embeddings.buffer, embeddings.byteOffset, embeddings.byteLength);\n  writeFileSync(outPath, buf);\n  const meta: EmbeddingsMeta = { shape: [n, dim], dtype: \"float32\", model };\n  writeFileSync(outPath + \".meta.json\", JSON.stringify(meta, null, 2) + \"\\n\", { encoding: \"utf-8\" });\n}\n" },
  { path: "src/rate-limiter.ts", text: "// Rate limiting — extracted from index.ts (B1 Phases 2 + 2b, TRDD-63314265).\n// Self-contained: depends only on Date/setTimeout/Math/stderr, so it imports\n// without index.ts's main()-on-import side effect. This module owns the whole\n// rate-limiting surface: the AIMD limiter class, the shared module-level\n// singleton + getAdaptiveRateLimiter() factory, the signalSuccess() /\n// signalRateLimitHit() accessors, and the rateLimitedParallel() executor (with\n// its ProgressFn callback type). index.ts imports rateLimitedParallel + the\n// accessors instead of holding any rate-limiting state of its own.\n//\n// Token-bucket rate limiter with Additive Increase / Multiplicative Decrease:\n//   - On 429 (rate limit hit): halve RPS immediately\n//   - On success streak (10 consecutive): increase RPS by 1 (up to initial max)\n\nexport class AdaptiveRateLimiter {\n  private tokens: number;\n  private lastRefill: number;\n  private currentRps: number;\n  private initialRps: number;\n  private readonly minRps: number = 1;\n  private refillPerMs: number;\n  private consecutiveSuccesses: number = 0;\n\n  constructor(rps: number) {\n    this.initialRps = Math.max(1, rps);\n    this.currentRps = this.initialRps;\n    this.tokens = this.currentRps;\n    this.refillPerMs = this.currentRps / 1000;\n    this.lastRefill = Date.now();\n  }\n\n  get rps(): number {\n    return this.currentRps;\n  }\n\n  private refill(): void {\n    const now = Date.now();\n    const elapsed = now - this.lastRefill;\n    if (elapsed > 0) {\n      this.tokens = Math.min(this.currentRps, this.tokens + elapsed * this.refillPerMs);\n      this.lastRefill = now;\n    }\n  }\n\n  private updateRate(newRps: number): void {\n    this.currentRps = Math.max(this.minRps, Math.min(this.initialRps, newRps));\n    this.refillPerMs = this.currentRps / 1000;\n    // Don't reset tokens — let existing tokens drain naturally\n  }\n\n  /** Wait until a token is available, then consume it. */\n  async acquire(): Promise<void> {\n    this.refill();\n    if (this.tokens >= 1) {\n      this.tokens -= 1;\n      return;\n    }\n    const waitMs = Math.ceil((1 - this.tokens) / this.refillPerMs);\n    await new Promise((r) => setTimeout(r, Math.max(1, waitMs)));\n    this.refill();\n    this.tokens = Math.max(0, this.tokens - 1);\n  }\n\n  /** Call after a successful request — additive increase */\n  onSuccess(): void {\n    this.consecutiveSuccesses++;\n    if (this.consecutiveSuccesses >= 10 && this.currentRps < this.initialRps) {\n      this.updateRate(this.currentRps + 1);\n      this.consecutiveSuccesses = 0;\n      process.stderr.write(`[llm-externalizer] AIMD: RPS increased to ${this.currentRps}\\n`);\n    }\n  }\n\n  /** Call after a 429 rate-limit error — multiplicative decrease */\n  onRateLimit(): void {\n    this.consecutiveSuccesses = 0;\n    const newRps = Math.floor(this.currentRps / 2);\n    if (newRps !== this.currentRps) {\n      this.updateRate(newRps);\n      process.stderr.write(`[llm-externalizer] AIMD: 429 detected, RPS halved to ${this.currentRps}\\n`);\n    }\n  }\n\n  /** Reset to initial RPS (e.g., after profile switch) */\n  reset(newInitialRps?: number): void {\n    if (newInitialRps !== undefined) {\n      this.initialRps = Math.max(1, newInitialRps);\n    }\n    this.currentRps = this.initialRps;\n    this.refillPerMs = this.currentRps / 1000;\n    this.tokens = this.currentRps;\n    this.consecutiveSuccesses = 0;\n    this.lastRefill = Date.now();\n  }\n}\n\n// ── ProgressFn — progress-notification callback ──────────────────────\n// (progress, total, message?) — used by the parallel executor's heartbeat\n// and by every batch tool to report incremental progress to the MCP client.\nexport type ProgressFn = (progress: number, total: number, message?: string) => void;\n\n// ── Module-level singleton — shared across ALL tool calls ────────────\n// One AIMD limiter per server process so every concurrent tool call shares\n// the same RPS budget (a 429 from any call backs off all of them).\nlet adaptiveRateLimiter: AdaptiveRateLimiter | null = null;\n\nfunction getAdaptiveRateLimiter(rps: number): AdaptiveRateLimiter {\n  if (!adaptiveRateLimiter || adaptiveRateLimiter.rps !== rps) {\n    adaptiveRateLimiter = new AdaptiveRateLimiter(rps);\n  }\n  return adaptiveRateLimiter;\n}\n\n// Accessors so callers outside this module can signal the shared singleton\n// without reaching into its binding. No-op until the singleton is created\n// (first rateLimitedParallel call) — preserves the prior `if (limiter)` guards.\nexport function signalRateLimitHit(): void {\n  if (adaptiveRateLimiter) adaptiveRateLimiter.onRateLimit();\n}\n\nexport function signalSuccess(): void {\n  if (adaptiveRateLimiter) adaptiveRateLimiter.onSuccess();\n}\n\n// ── Rate-limited parallel executor ───────────────────────────────────\n// Dispatches tasks respecting two independent limits:\n//   1. RPS (rate): max N new tasks started per second (adaptive token bucket)\n//   2. maxInFlight: max N tasks running simultaneously (safety cap)\n// Workers grab the next task, wait for a rate-limit token, then execute.\n// Results are returned in original order.\n//\n// No wall-clock deadline: Claude Code's MCP timeout is an INACTIVITY timeout\n// (no progress for 1800s), not a hard deadline. As long as progress notifications\n// keep flowing, the tool call can run indefinitely. A heartbeat timer sends\n// progress every 30s to keep the connection alive even during slow LLM calls.\n\nconst DEFAULT_MAX_IN_FLIGHT = 200;\n// Exported: chatCompletionSimple()'s per-request heartbeat in index.ts reuses\n// the SAME interval (single source of truth for the MCP keep-alive cadence).\nexport const HEARTBEAT_INTERVAL_MS = 30_000; // 30s — well under 1800s inactivity timeout\n\nexport async function rateLimitedParallel<T>(\n  tasks: (() => Promise<T>)[],\n  rps: number,\n  maxInFlight: number = DEFAULT_MAX_IN_FLIGHT,\n  onProgress?: ProgressFn,\n): Promise<T[]> {\n  if (tasks.length === 0) return [];\n  const results: T[] = new Array(tasks.length);\n  const limiter = getAdaptiveRateLimiter(rps);\n  let nextIndex = 0;\n  let completedCount = 0;\n\n  // Heartbeat: send progress notifications every 30s to prevent inactivity timeout\n  const heartbeat = onProgress\n    ? setInterval(() => {\n        onProgress(completedCount, tasks.length, `Processing: ${completedCount}/${tasks.length} done (${limiter.rps} RPS)`);\n      }, HEARTBEAT_INTERVAL_MS)\n    : null;\n\n  try {\n    async function worker() {\n      while (true) {\n        const i = nextIndex;\n        if (i >= tasks.length) return;\n        nextIndex++;\n        await limiter.acquire();\n        results[i] = await tasks[i]();\n        completedCount++;\n        // Notify on each completion too (supplements heartbeat)\n        if (onProgress) {\n          onProgress(completedCount, tasks.length, `Done: ${completedCount}/${tasks.length}`);\n        }\n      }\n    }\n\n    const workerCount = Math.min(Math.max(1, maxInFlight), tasks.length);\n    await Promise.all(Array.from({ length: workerCount }, () => worker()));\n  } finally {\n    if (heartbeat) clearInterval(heartbeat);\n  }\n  return results;\n}\n" },
  { path: "src/security_scan/report.ts", text: "/**\n * Report — fan group verdicts back out to per-id results, aggregate the\n * summary, render JSON + markdown, and write both to disk. The tool itself\n * returns ONLY the paths + a one-line counter (TRDD §4); all detail lives in\n * these two files.\n *\n * The timestamp / slug / report-dir helpers are re-implemented locally (no\n * mass_scouting import) and honor the agent-reports-location rule: local time\n * + GMT offset, under <main-root>/reports/security_scan/ unless output_dir is\n * given.\n */\n\nimport { mkdirSync, writeFileSync } from \"node:fs\";\nimport { isAbsolute, join, resolve } from \"node:path\";\nimport { resolveProjectMainRoot } from \"../project-root\";\n\nimport type { GroupVerdict } from \"./judge\";\nimport type { DedupGroup, SkippedRecord } from \"./intake\";\nimport {\n  VERDICTS,\n  type SecurityScanItemResult,\n  type SecurityScanReport,\n  type SecurityScanSummary,\n  type Verdict,\n} from \"./types\";\n\n// ── Path helpers (local, agent-reports-location compliant) ───────────────\n\nfunction defaultMainRoot(): string {\n  // Single source of truth — see project-root.ts.\n  return resolveProjectMainRoot();\n}\n\n/** Resolve the report directory. Explicit output_dir wins; else <root>/reports/security_scan/. */\nexport function resolveReportDir(\n  outputDir: string | undefined,\n  mainRoot?: string,\n): string {\n  if (outputDir && outputDir.length > 0) {\n    return isAbsolute(outputDir) ? outputDir : resolve(process.cwd(), outputDir);\n  }\n  return join(mainRoot ?? defaultMainRoot(), \"reports\", \"security_scan\");\n}\n\n/** Local-time + GMT-offset compact stamp: YYYYMMDD_HHMMSS±HHMM. */\nexport function isoTimestampLocal(now: Date = new Date()): string {\n  const pad = (n: number, w = 2): string => String(n).padStart(w, \"0\");\n  const tzMin = -now.getTimezoneOffset();\n  const tzSign = tzMin >= 0 ? \"+\" : \"-\";\n  const tzAbs = Math.abs(tzMin);\n  return (\n    `${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}` +\n    `_${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}` +\n    `${tzSign}${pad(Math.floor(tzAbs / 60))}${pad(tzAbs % 60)}`\n  );\n}\n\nexport function slugify(s: string): string {\n  return s.replace(/[^A-Za-z0-9._-]+/g, \"-\").slice(0, 80) || \"job\";\n}\n\n// ── Aggregation ──────────────────────────────────────────────────────────\n\nexport interface AggregateInput {\n  jobId: string;\n  model: string;\n  groups: DedupGroup[];\n  verdicts: GroupVerdict[];\n  skipped: SkippedRecord[];\n  recordsTotal: number;\n  budgetSpent: number;\n  /** Items refused because the whole-job budget gate failed. */\n  itemsSkippedOverBudget: number;\n}\n\n/**\n * Fan each group's verdict out to every member id, build per-item rows, and\n * compute the summary. `groups[i]` is paired with `verdicts[i]` by index\n * (judgeGroups preserves order).\n */\nexport function aggregate(input: AggregateInput): SecurityScanReport {\n  const items: SecurityScanItemResult[] = [];\n  const verdictByKey = new Map<string, GroupVerdict>();\n  for (const v of input.verdicts) verdictByKey.set(v.key, v);\n\n  for (const g of input.groups) {\n    const gv = verdictByKey.get(g.key);\n    if (!gv) continue; // unreachable — every group has a verdict.\n    for (const m of g.members) {\n      const item: SecurityScanItemResult = {\n        id: m.id,\n        category: m.category,\n        verdict: gv.payload.verdict,\n        confidence: gv.payload.confidence,\n        reason: gv.payload.reason,\n        injection_observed: gv.payload.injection_observed,\n        injection_markers: gv.injectionMarkers,\n        model: input.model,\n        dedup_group: g.key,\n        // F9: carry the per-group fail-safe flag through to every fanned item.\n        fail_safe: gv.failSafe,\n      };\n      if (m.file_path !== undefined) item.file_path = m.file_path;\n      if (m.line !== undefined) item.line = m.line;\n      items.push(item);\n    }\n  }\n\n  // Skipped items are reported too, as uncertain rows with the skip reason, so\n  // the caller never silently loses a finding.\n  for (const s of input.skipped) {\n    const item: SecurityScanItemResult = {\n      id: s.id,\n      category: s.category,\n      verdict: \"uncertain\",\n      confidence: 0,\n      reason: `Skipped during intake: ${s.reason}`,\n      injection_observed: false,\n      injection_markers: [],\n      model: input.model,\n      dedup_group: \"(skipped)\",\n      // F9: a skipped item was never judged → fail-safe by definition.\n      fail_safe: true,\n    };\n    if (s.file_path !== undefined) item.file_path = s.file_path;\n    items.push(item);\n  }\n\n  const counts_by_verdict: Record<Verdict, number> = {\n    threat: 0,\n    not_threat: 0,\n    uncertain: 0,\n  };\n  const counts_by_category: Record<string, number> = {};\n  for (const it of items) {\n    counts_by_verdict[it.verdict]++;\n    counts_by_category[it.category] = (counts_by_category[it.category] ?? 0) + 1;\n  }\n\n  const summary: SecurityScanSummary = {\n    counts_by_verdict,\n    counts_by_category,\n    items_total: items.length,\n    items_deduped: Math.max(0, input.recordsTotal - input.groups.length),\n    items_skipped_too_big: input.skipped.filter((s) =>\n      s.reason.startsWith(\"content \"),\n    ).length,\n    budget_usd_spent: input.budgetSpent,\n    items_skipped_over_budget: input.itemsSkippedOverBudget,\n  };\n\n  return {\n    job_id: input.jobId,\n    model: input.model,\n    generated_at: new Date().toISOString(),\n    summary,\n    items,\n  };\n}\n\n// ── Markdown render ──────────────────────────────────────────────────────\n\nexport function renderMarkdown(report: SecurityScanReport): string {\n  const s = report.summary;\n  const lines: string[] = [];\n  lines.push(`# Security-scan report — ${report.job_id}`, \"\");\n  lines.push(`- Model: \\`${report.model}\\``);\n  lines.push(`- Generated: ${report.generated_at}`);\n  lines.push(`- Items total: ${s.items_total}`);\n  lines.push(`- Deduped (judged once, fanned out): ${s.items_deduped}`);\n  lines.push(`- Skipped (too big): ${s.items_skipped_too_big}`);\n  lines.push(`- Skipped (over budget): ${s.items_skipped_over_budget}`);\n  lines.push(`- Budget spent: $${s.budget_usd_spent.toFixed(6)}`);\n  lines.push(\"\");\n  lines.push(\"## Counts by verdict\", \"\");\n  lines.push(\"| Verdict | Count |\", \"| --- | --- |\");\n  for (const v of VERDICTS) {\n    lines.push(`| ${v} | ${s.counts_by_verdict[v]} |`);\n  }\n  lines.push(\"\");\n  lines.push(\"## Counts by category\", \"\");\n  lines.push(\"| Category | Count |\", \"| --- | --- |\");\n  for (const [c, n] of Object.entries(s.counts_by_category).sort(\n    (a, b) => b[1] - a[1],\n  )) {\n    lines.push(`| ${mdCell(c)} | ${n} |`);\n  }\n  lines.push(\"\");\n  lines.push(\"## Items\", \"\");\n  lines.push(\n    \"| id | category | verdict | conf | injection | reason |\",\n    \"| --- | --- | --- | --- | --- | --- |\",\n  );\n  // Threats first, then uncertain, then not_threat — most actionable on top.\n  const order: Record<Verdict, number> = {\n    threat: 0,\n    uncertain: 1,\n    not_threat: 2,\n  };\n  const sorted = [...report.items].sort(\n    (a, b) => order[a.verdict] - order[b.verdict] || b.confidence - a.confidence,\n  );\n  for (const it of sorted) {\n    const inj = it.injection_observed\n      ? `yes${it.injection_markers.length > 0 ? ` (${it.injection_markers.join(\",\")})` : \"\"}`\n      : it.injection_markers.length > 0\n        ? `markers: ${it.injection_markers.join(\",\")}`\n        : \"no\";\n    lines.push(\n      `| ${mdCell(it.id)} | ${mdCell(it.category)} | ${it.verdict} | ${it.confidence.toFixed(2)} | ${mdCell(inj)} | ${mdCell(it.reason)} |`,\n    );\n  }\n  lines.push(\"\");\n  return lines.join(\"\\n\");\n}\n\n/** Escape a value for a single markdown table cell (no pipe/newline breakage). */\nfunction mdCell(s: string): string {\n  return s.replace(/\\|/g, \"\\\\|\").replace(/\\n/g, \" \").slice(0, 400);\n}\n\n// ── Write ────────────────────────────────────────────────────────────────\n\nexport interface WrittenReport {\n  jsonPath: string;\n  mdPath: string;\n}\n\n/**\n * Write the JSON + markdown report to `reportDir`, returning both paths.\n * Filenames: <stamp>-security-scan-<job>.{json,md}.\n */\nexport function writeReport(\n  report: SecurityScanReport,\n  reportDir: string,\n): WrittenReport {\n  mkdirSync(reportDir, { recursive: true });\n  const stamp = isoTimestampLocal();\n  const base = `${stamp}-security-scan-${slugify(report.job_id)}`;\n  const jsonPath = join(reportDir, `${base}.json`);\n  const mdPath = join(reportDir, `${base}.md`);\n  writeFileSync(jsonPath, JSON.stringify(report, null, 2) + \"\\n\", \"utf-8\");\n  writeFileSync(mdPath, renderMarkdown(report), \"utf-8\");\n  return { jsonPath, mdPath };\n}\n" },
  { path: "src/ensemble-limits.ts", text: "// ── Ensemble per-model limits (A3, TRDD-828238b5) ──────────────────────\n//\n// Two fields with DIFFERENT provenance — DO NOT conflate them:\n//\n//   • maxOutput      — the output-token budget we REQUEST from the model. The\n//     provider's own cap (catalog `top_provider.max_completion_tokens`) is the\n//     authority here and providers occasionally RAISE it, so it is preferred\n//     LIVE from the warm 1h-TTL catalog cache (see resolveEnsembleModelLimits).\n//     The literals below are the cold-cache fallback only. Requesting more\n//     output than a model wants is harmless — the model self-limits (e.g.\n//     grok-4.1-fast abbreviates, using ~10% of the budget) — so a higher live\n//     value never degrades quality.\n//\n//   • maxInputLines  — how many source LINES we FEED the model. This is an\n//     EMPIRICAL QUALITY cap, deliberately far below each model's architectural\n//     context (e.g. grok 20K lines despite its multi-hundred-K-token context)\n//     to avoid long-context quality degradation. The catalog does NOT carry a\n//     per-model line budget, so this field is NEVER auto-derived from the\n//     catalog and MUST stay hand-calibrated. A future maintainer must not\n//     \"de-hardcode\" it into a context_length fraction — that regresses quality.\n\nexport interface ModelLimits {\n  /** Output-token budget to request (catalog-preferred, see module note). */\n  maxOutput: number;\n  /** Input LINE cap — empirical quality calibration, never catalog-derived. */\n  maxInputLines: number;\n}\n\n/**\n * Calibrated per-model limits. `maxOutput` here is the cold-cache fallback;\n * `maxInputLines` is the authoritative quality cap (catalog has no equivalent).\n */\nexport const KNOWN_MODEL_LIMITS: Record<string, ModelLimits> = {\n  \"x-ai/grok-4.1-fast\": { maxOutput: 30_000, maxInputLines: 20_000 },\n  \"google/gemini-2.5-flash\": { maxOutput: 65_535, maxInputLines: 50_000 },\n  // Qwen 3.6 Plus: 1M context, 65K max output.\n  \"qwen/qwen3.6-plus\": { maxOutput: 65_535, maxInputLines: 40_000 },\n  // Nemotron 3 Super: 262K context, free on OpenRouter. Conservative 40K-line\n  // input cap to avoid quality degradation on very long contexts.\n  \"nvidia/nemotron-3-super-120b-a12b:free\": { maxOutput: 65_535, maxInputLines: 40_000 },\n};\n\n/** Fallback for any model not in KNOWN_MODEL_LIMITS (and cold catalog). */\nexport const DEFAULT_MODEL_LIMITS: ModelLimits = { maxOutput: 32_000, maxInputLines: 30_000 };\n\n/**\n * Catalog `max_completion_tokens` values below this are implausible (truncated\n * or garbage) and are ignored in favour of the calibrated fallback. 1024 is a\n * floor no real chat model undercuts for its output cap.\n */\nexport const MIN_PLAUSIBLE_MAX_OUTPUT = 1024;\n\n/**\n * Resolve one model's ensemble limits, preferring the live catalog for the\n * catalog-authoritative field and keeping the empirical field hand-calibrated.\n *\n * @param id              model id\n * @param catalogMaxOutput live `top_provider.max_completion_tokens` from the\n *                         warm 1h-TTL catalog cache, or `undefined` when the\n *                         cache is cold or the model is absent from it\n * @param known           calibrated table (injectable for tests)\n * @param fallback        default when the id is in neither catalog nor table\n *\n * maxOutput     ← live catalog (if present & ≥ floor) → known[id] → fallback\n * maxInputLines ← known[id] → fallback                (NEVER from the catalog)\n */\nexport function resolveEnsembleModelLimits(\n  id: string,\n  catalogMaxOutput: number | undefined,\n  known: Record<string, ModelLimits> = KNOWN_MODEL_LIMITS,\n  fallback: ModelLimits = DEFAULT_MODEL_LIMITS,\n): ModelLimits {\n  const knownEntry = known[id];\n  const maxInputLines = knownEntry?.maxInputLines ?? fallback.maxInputLines;\n  const liveMaxOutput =\n    typeof catalogMaxOutput === \"number\" &&\n    Number.isFinite(catalogMaxOutput) &&\n    catalogMaxOutput >= MIN_PLAUSIBLE_MAX_OUTPUT\n      ? Math.floor(catalogMaxOutput)\n      : undefined;\n  const maxOutput = liveMaxOutput ?? knownEntry?.maxOutput ?? fallback.maxOutput;\n  return { maxOutput, maxInputLines };\n}\n" },
  { path: "src/select-common.ts", text: "/**\n * Generic same-or-cheaper selection gate (TRDD-828238b5 A6, extracted from\n * security-triage/select.ts so every per-tool benchmark reuses ONE gate\n * instead of re-implementing the three-gate math).\n *\n * The gate is the user's standing rule made mechanical: a candidate may\n * become a tool's default ONLY if it clears THREE independent gates —\n *   1. REQUIREMENTS — passed the tool's own qualify() (carried in\n *      `qualified` + `disqualifyReason`).\n *   2. BENCHMARK — passed that tool's golden-dataset benchmark\n *      (`benchmarkPass` + `benchmarkScore` + `benchmarkFailReasons`).\n *   3. COST — is NOT pricier than the incumbent default on EITHER axis. We\n *      never auto-bump to a pricier model. Among eligible same-or-cheaper\n *      passers, the best benchmark score wins (ties → lower cost → lower\n *      latency, mirroring pickTopN).\n *\n * Pure module — no network, no IO, fully unit-testable. The rejection /\n * recommendation messages are PARAMETERIZED via `requirementsLabel` and\n * `benchmarkLabel` so each tool reproduces its own wording (security-triage\n * keeps \"security-triage requirements\" / \"the triage benchmark\" byte-for-byte).\n */\n\n/** Tiny tolerance for float pricing noise when comparing $/M values. */\nexport const COST_EPSILON = 1e-9;\n\n/**\n * One candidate, tool-agnostic. Every per-tool selector maps its own assessment\n * shape onto this before calling selectSameOrCheaper, and maps the result back.\n */\nexport interface GenericCandidate {\n  modelId: string;\n  /** Passed the tool's qualify() against its per-tool requirements. */\n  qualified: boolean;\n  /** Why it failed qualify (when qualified === false). */\n  disqualifyReason?: string;\n  inputDollarsPerMillion: number;\n  outputDollarsPerMillion: number;\n  /** Mean per-call latency over the dataset run (ms). 0 when unknown. */\n  latencyMs: number;\n  /** Passed the tool's golden-dataset benchmark. */\n  benchmarkPass: boolean;\n  /** The benchmark score used to rank eligible passers (higher is better). */\n  benchmarkScore: number;\n  /** Why the benchmark failed (joined into the rejection reason). */\n  benchmarkFailReasons: string[];\n}\n\nexport interface GenericSelectionInput {\n  candidates: GenericCandidate[];\n  /** The current default model id for this tool. */\n  incumbentModelId: string;\n  incumbentInputDollarsPerMillion: number;\n  incumbentOutputDollarsPerMillion: number;\n  /**\n   * Label for the per-tool requirements in the \"does not meet …\" rejection\n   * (e.g. \"security-triage requirements\" / \"search-existing requirements\").\n   */\n  requirementsLabel: string;\n  /**\n   * Label for the per-tool benchmark in the recommendation reason\n   * (e.g. \"the triage benchmark\" / \"the search-existing benchmark\").\n   */\n  benchmarkLabel: string;\n}\n\nexport interface GenericRejectedCandidate {\n  modelId: string;\n  reason: string;\n}\n\nexport interface GenericSelectionResult {\n  /** The model the benchmark recommends as the tool's default. */\n  recommendedModelId: string;\n  /** True iff the recommendation differs from the incumbent. */\n  changed: boolean;\n  reason: string;\n  /** Eligible passers (qualified + benchmark-pass + not-pricier), best-first. */\n  eligible: GenericCandidate[];\n  /** Candidates that failed one of the gates, with the reason. */\n  rejected: GenericRejectedCandidate[];\n}\n\n/** Is `candidate` NOT pricier than the incumbent on either axis? */\nexport function notPricier(\n  candidate: GenericCandidate,\n  inInc: number,\n  outInc: number,\n): boolean {\n  return (\n    candidate.inputDollarsPerMillion <= inInc + COST_EPSILON &&\n    candidate.outputDollarsPerMillion <= outInc + COST_EPSILON\n  );\n}\n\n/**\n * Apply the three gates and pick the winner. Deterministic, pure.\n *\n * If no eligible same-or-cheaper passer exists, the incumbent is kept\n * (changed=false) — the gate NEVER recommends a pricier model and never\n * leaves the tool without a default.\n *\n * Message wording is parameterized: the security-triage selector passes\n * requirementsLabel=\"security-triage requirements\" and benchmarkLabel=\"the\n * triage benchmark\", reproducing its original strings exactly.\n */\nexport function selectSameOrCheaper(\n  input: GenericSelectionInput,\n): GenericSelectionResult {\n  const {\n    incumbentModelId,\n    incumbentInputDollarsPerMillion: inInc,\n    incumbentOutputDollarsPerMillion: outInc,\n    requirementsLabel,\n    benchmarkLabel,\n  } = input;\n\n  const eligible: GenericCandidate[] = [];\n  const rejected: GenericRejectedCandidate[] = [];\n\n  for (const c of input.candidates) {\n    if (!c.qualified) {\n      rejected.push({\n        modelId: c.modelId,\n        reason: `does not meet ${requirementsLabel}${c.disqualifyReason ? ` (${c.disqualifyReason})` : \"\"}`,\n      });\n      continue;\n    }\n    if (!c.benchmarkPass) {\n      rejected.push({\n        modelId: c.modelId,\n        reason: `failed ${benchmarkLabel}: ${c.benchmarkFailReasons.join(\"; \")}`,\n      });\n      continue;\n    }\n    if (!notPricier(c, inInc, outInc)) {\n      rejected.push({\n        modelId: c.modelId,\n        reason: `pricier than the incumbent default (in $${c.inputDollarsPerMillion.toFixed(3)}/out $${c.outputDollarsPerMillion.toFixed(3)} vs incumbent in $${inInc.toFixed(3)}/out $${outInc.toFixed(3)}) — never auto-bump to a pricier model`,\n      });\n      continue;\n    }\n    eligible.push(c);\n  }\n\n  eligible.sort((a, b) => {\n    if (b.benchmarkScore !== a.benchmarkScore) return b.benchmarkScore - a.benchmarkScore;\n    const aCost = a.inputDollarsPerMillion + a.outputDollarsPerMillion;\n    const bCost = b.inputDollarsPerMillion + b.outputDollarsPerMillion;\n    if (aCost !== bCost) return aCost - bCost;\n    return a.latencyMs - b.latencyMs;\n  });\n\n  if (eligible.length === 0) {\n    return {\n      recommendedModelId: incumbentModelId,\n      changed: false,\n      reason: `No eligible same-or-cheaper model passed ${benchmarkLabel}. Keeping the incumbent default.`,\n      eligible,\n      rejected,\n    };\n  }\n\n  const winner = eligible[0];\n  const changed = winner.modelId !== incumbentModelId;\n  return {\n    recommendedModelId: winner.modelId,\n    changed,\n    reason: changed\n      ? `${winner.modelId} passed ${benchmarkLabel} (score ${winner.benchmarkScore.toFixed(3)}) at no higher cost than the incumbent and scored best among eligible passers.`\n      : `The incumbent ${winner.modelId} remains the best eligible passer (score ${winner.benchmarkScore.toFixed(3)}).`,\n    eligible,\n    rejected,\n  };\n}\n" },
];
